560	// 读取 -> 解析 -> 严格校验；任何一步失败都抛出含文件路径与可定位原因的错误
561	async function loadSpecsFromFile(configPath: string): Promise<EndpointSpec[]> {
562	  let text: string;
563	  try {
564	    text = await readFile(configPath, 'utf8');
565	  } catch (e) {
566	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
567	  }
568	
569	  let raw: unknown;
570	  try {
571	    raw = JSON.parse(text);
572	  } catch (e) {
573	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
574	  }
575	
576	  try {
577	    return validateConfig(raw);
578	  } catch (e) {
579	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
580	  }
581	}
