959	// 模块级运行时句柄（启动后赋值）
960	let activeState: LiveState;
961	let server: http.Server;
962	let configFile = '';
963	let shuttingDown = false;
964	
965	// 尚未发出的延迟响应定时器，关闭时统一取消
966	const pendingTimers = new Set<ReturnType<typeof setTimeout>>();
967	
968	// 重载按“触发顺序”串行处理：后一个 reload 必定在前一个落定后才读文件
969	let reloadChain: Promise<unknown> = Promise.resolve();
970	
971	function triggerReload(): Promise<ReloadResult> {
972	  const job = reloadChain.then(async (): Promise<ReloadResult> => {
973	    try {
974	      // 校验通过前只构造局部变量，任何失败都不会触碰 activeState
975	      const next = await loadStateFromFile(configFile, activeState.version + 1);
976	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
977	      return { ok: true, version: activeState.version };
978	    } catch (e) {
979	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
980	      return { ok: false, version: activeState.version, error: describeError(e) };
981	    }
982	  });
983	  // 失败也不能打断后续 reload 的排队
984	  reloadChain = job.then(
985	    () => undefined,
986	    () => undefined,
987	  );
988	  return job;
989	}
