function writeResponse(
  res: http.ServerResponse,
  status: number,
  headers: { readonly [name: string]: string },
  body: string,
  record?: RequestRecord,
): void {
  if (record) {
    // 发送完成 = 服务器完成写出（不代表客户端已收到）；写出完成前连接断开或
    // 发送失败 = 中断。finish 先于 close 到达，settled 保证完成后不被覆盖。
    let settled = false;
    const mark = (state: RecordState): void => {
      if (!settled) {
        settled = true;
        record.state = state;
      }
    };
    res.once('finish', () => mark('sent'));
    res.once('close', () => mark('interrupted'));
    if (res.destroyed) {
      // 延迟期间客户端已断开：close 已发过，不会再触发
      mark('interrupted');
    }
  }
  try {
    res.writeHead(status, headers);
    res.end(body === '' ? undefined : body);
  } catch {
    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
    if (record) {
      record.state = 'interrupted';
    }
  }
}
