    sendJson(res, 200, { version: activeState.version, records: [...records.values()] }, activeState.version);
    return;
  }
  if (pathname === REQUESTS_CLEAR_PATH && method === 'POST') {
    // 移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
